// Pick a Drive image that has not been posted yet, plus a rotating caption.
//
// Dedup: workflow staticData persists postedIds across runs. When all files
// have been posted, the list resets so the rotation continues (warned via
// cycleReset = true so the run can be inspected in the n8n executions log).
//
// Caption rotation: 4-week cycle [météo → humour → QR → crew], anchored on
// Sat 2026-05-02 22:00 UTC = Sat 00:00 Europe/Paris (matches
// newsletter/sendEmail.js).

const response = $input.first().json;
const files = (response && response.files) || [];
if (files.length === 0) {
  throw new Error('Drive folder returned no images. Check folder ID and OAuth scope.');
}

const staticData = $getWorkflowStaticData('global');
staticData.postedIds = Array.isArray(staticData.postedIds) ? staticData.postedIds : [];

let pool = files.filter((f) => !staticData.postedIds.includes(f.id));
let cycleReset = false;
if (pool.length === 0) {
  staticData.postedIds = [];
  pool = files.slice();
  cycleReset = true;
}

// Deterministic pick: alphabetical name order on the unposted pool.
pool.sort((a, b) => String(a.name).localeCompare(String(b.name)));
const pick = pool[0];
staticData.postedIds.push(pick.id);

// Public Drive CDN URL — requires the n8n folder to be shared
// "Anyone with the link → Viewer" (one-time Drive setting).
const imageUrl = `https://lh3.googleusercontent.com/d/${pick.id}=w2000`;

// Week-based caption rotation
const EPOCH = Date.UTC(2026, 4, 1, 22, 0, 0);
const week = Math.floor((Date.now() - EPOCH) / (7 * 24 * 60 * 60 * 1000));
const captions = [
  // 0 — météo
  `Si la météo tient ses promesses, c'est week-end glace les pieds dans l'herbe.\n\nOn vous attend face à la mairie de La Frette-sur-Seine, samedi & dimanche, 14h–19h.\n\nCrêpes · gaufres · glaces artisanales\n#glaceenseine`,
  // 1 — humour
  `Y'a des jours où t'as juste pas envie de réfléchir. Bonne nouvelle, on a tout prévu.\n\nTu marches, tu pointes, tu manges.\nQuai de La Frette-sur-Seine, sam & dim, 14h–19h.\n#glaceenseine`,
  // 2 — QR
  `Hésiter entre douze parfums, ça fatigue. Sur place, scanne le QR du menu : un mini-jeu te tire un parfum au hasard.\n\nDécision : 0,3 seconde.\n\nCe week-end, sam & dim, 14h–19h, face à la mairie de La Frette-sur-Seine.\n#glaceenseine`,
  // 3 — crew
  `Le gang Glace en Seine te garde une place ce week-end. Banc, herbe, marches du quai — choisis ton spot.\n\nSamedi & dimanche, 14h–19h, face à la mairie de La Frette-sur-Seine.\nCrêpes · gaufres · glaces artisanales\n#glaceenseine`
];
const caption = captions[((week % captions.length) + captions.length) % captions.length];

return [
  {
    json: {
      week,
      pickedId: pick.id,
      pickedName: pick.name,
      imageUrl,
      caption,
      cycleReset,
      postedCount: staticData.postedIds.length,
      poolSize: files.length
    }
  }
];
